@app.post("/api/v1/verify-key")
async def verify_key(request: dict):
    """Endpoint to verify an API key for service-to-service auth."""
    provided_key = request.get("api_key", "")
    if not provided_key:
        raise HTTPException(status_code=400, detail="Missing api_key")

    # Vulnerable: byte-by-byte comparison leaks timing information
    is_valid = verify_api_key(provided_key, API_SECRET)

    if is_valid:
        return {"status": "authenticated", "permissions": ["read", "write"]}
    raise HTTPException(status_code=401, detail="Invalid API key")

@app.post("/api/v1/login")
async def login(credentials: HTTPBasicCredentials = Depends(security)):
    user = authenticate_user(credentials.username, credentials.password)
    if user is None:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_urlsafe(32)
    return {"token": token, "role": user["role"]}

@app.get("/api/v1/admin/users")
async def list_users(credentials: HTTPBasicCredentials = Depends(security)):
    user = authenticate_user(credentials.username, credentials.password)
    if user is None or user["role"] != "admin":
        raise HTTPException(status_code=403, detail="Forbidden")
    with get_db() as cursor:
        cursor.execute("SELECT id, username, role FROM users")
        return [{"id": r[0], "username": r[1], "role": r[2]} for r in cursor.fetchall()]

